const rows = $input.first().json.values, d = {};
const first = f => rows.findIndex(f);
const set = (i, v, why) => { if (i >= 0) d[i] = [v, why]; };
set(first(r => r[7] === "sure"), "accept", "sure merge");
set(rows.findIndex((r, i) => r[7] === "sure" && !d[i]), "accept", "sure merge, record edited after scan -> stale_skipped");
set(first(r => r[7] === "borderline" && (r[8] || "").startsWith("likely_duplicate")), "accept", "borderline merge");
set(first(r => r[7] === "borderline" && (r[8] || "").startsWith("likely_not_duplicate")), "reject", "reject");
rows.forEach((r, i) => { if (["fill", "missing_task"].includes(r[2])) set(i, "accept", r[2] + " " + r[4]); });
set(first(r => r[2] === "stale_task"), "accept", "stale task");
const data = Object.entries(d).map(([i, [v]]) => ({ range: "proposals!J" + (Number(i) + 2), values: [[v]] }));
return [{ json: { data, picked: Object.entries(d).map(([i, [v, why]]) => [Number(i) + 2, v, why, rows[i][0]]) } }];
